-- Полная история production_day, включая D; независимая проверка ключей, hashdiff, даты и numeric(18,3).
WITH expected AS (SELECT lower(to_hex(md5(to_utf8('production:' || entity_id)))) AS production_hk,lower(to_hex(md5(to_utf8('production_day_well:' || entity_id || ':' || json_extract_scalar(payload,'$.well_id'))))) AS link_hk,event_id,entity_version,op,event_time,lower(to_hex(md5(to_utf8(op || ':' || payload)))) AS hashdiff,try_cast(json_extract_scalar(payload,'$.production_date') AS date) AS production_date,try_cast(json_extract_scalar(payload,'$.oil_tonnes') AS decimal(18,3)) AS oil_tonnes,json_extract_scalar(payload,'$.status') AS status FROM {{target:oil_dds__event}} WHERE event_type='production_day'), actual AS (SELECT production_hk,link_hk,event_id,entity_version,op,event_time,hashdiff,production_date,oil_tonnes,status FROM {{target:oil_dds__sat_daily_production}}) SELECT count(*) AS n FROM ((SELECT * FROM expected EXCEPT ALL SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT ALL SELECT * FROM expected)) q;
